pub fn extract(condition: Vec<bool>, arr: Vec<f32>) -> Vec<f32> {
    condition
        .into_iter()
        .zip(arr.into_iter())
        .filter_map(|(flag, value)| if flag { Some(value) } else { None })
        .collect()
}

